static _CLG_NF4_VAR1_SPLINE: OnceLock<RectBivariateSpline> = OnceLock::new();

/// Returns the degree-(3,3) interpolating spline over `CLg_nf4_var1`.
///
/// The spline is constructed on the **first call only**; every subsequent
